from pathlib import Path
from html import escape
OUT=Path('docs/public/diagrams');OUT.mkdir(parents=True,exist_ok=True)
STYLE='''<style>text{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;fill:#26344b;font-size:15px}.node{fill:#fff;stroke:#9dabc0;stroke-width:1.4}.accent{fill:#edf3ff;stroke:#3569cf}.boundary{fill:#f7f9fc;stroke:#9dabc0;stroke-dasharray:6 5}.edge{fill:none;stroke:#63748f;stroke-width:1.6;marker-end:url(#arrow)}.label{font-size:12px;fill:#526079}.title{font-size:20px;font-weight:600}.small{font-size:12px}@media(prefers-color-scheme:dark){text{fill:#e5ecfa}.node{fill:#242e3d;stroke:#7d8eab}.accent{fill:#213a61;stroke:#86b2ff}.boundary{fill:#1b2431;stroke:#7d8eab}.label{fill:#bdc9dd}.edge{stroke:#a6b9d7}}</style>'''
def svg(name,title,w,h,nodes,edges,extra=''):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">中文教学结构图，节点和箭头表示应用可观察的数据流；不是模型内部推理。</desc>{STYLE}<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#7185a4"/></marker></defs><text x="24" y="32" class="title">{escape(title)}</text>'+extra
 for path,label,lx,ly in edges:
  s+=f'<path d="{path}" class="edge"/>'
  if label:s+=f'<text x="{lx}" y="{ly}" class="label">{escape(label)}</text>'
 for x,y,nw,nh,lines,accent in nodes:
  s+=f'<rect x="{x}" y="{y}" width="{nw}" height="{nh}" rx="7" class="node {"accent" if accent else ""}"/>'
  for j,line in enumerate(lines.split('|')):
   s+=f'<text x="{x+nw/2}" y="{y+nh/2+(j-(len(lines.split("|"))-1)/2)*21+5}" text-anchor="middle">{escape(line)}</text>'
 s+='</svg>';(OUT/(name+'.svg')).write_text(s)
